        steps:[{title:'Establish baseline',detail:'Record loss curves, gradient norms, throughput and validation metrics.',input:'Model, data and optimizer',output:'Training diagnostics',failure:'Only the final loss is inspected.'},{title:'Diagnose instability',detail:'Check data, masks, loss scale, gradient magnitude and update size.',input:'Divergent or stalled training',output:'Root-cause hypothesis',failure:'Changing several hyperparameters at once.'},{title:'Tune schedule',detail:'Compare optimizer and learning-rate schedules on controlled runs.',input:'Baseline configuration',output:'Stable optimization recipe',failure:'Schedule changes are not reproducible.'},{title:'Verify generalization',detail:'Evaluate held-out data and multiple seeds where needed.',input:'Selected checkpoint',output:'Robust performance estimate',failure:'Best training checkpoint is mistaken for best generalizing model.'}],
        question:{prompt:'What does gradient clipping primarily protect against?',options:['All forms of overfitting','Extremely large gradient updates such as exploding gradients','Incorrect labels','Data leakage between train and test'],explanation:'Clipping bounds gradient magnitude before an optimizer update; it does not solve unrelated data or generalization problems.'},
        project:'Train a small MLP on a public dataset. Compare SGD, momentum and AdamW; plot loss and gradient norms; deliberately test a too-large learning rate and explain the failure.',
        pitfalls:['Treating Adam as a substitute for a validation strategy.','Ignoring NaNs and silently continuing training.','Clipping gradients without checking why they explode.','Comparing optimizers with different compute budgets.'],next:'Regularization, normalization and generalization'
