        steps:[{title:'Diagnose generalization gap',detail:'Compare training and validation curves and audit duplicates and leakage.',input:'Learning curves',output:'Overfit hypothesis',failure:'Regularization hides a data-quality problem.'},{title:'Select controls',detail:'Choose weight decay, dropout, normalization and augmentation for the architecture.',input:'Architecture and data',output:'Controlled regularization plan',failure:'Incompatible or excessive regularization.'},{title:'Tune with validation',detail:'Change one family at a time and monitor both train and validation behavior.',input:'Candidate configurations',output:'Selected regularization',failure:'Validation set becomes overused.'},{title:'Check inference mode',detail:'Verify dropout and normalization behave correctly at evaluation and serving.',input:'Saved model',output:'Consistent inference behavior',failure:'Training-mode layers remain enabled in production.'}],
